def minimumValueSum(nums, andValues):
    INF = float('inf')
    m = len(andValues)
    # closed[k]: min sum when exactly k parts are finished and end at the previous element
    closed = [INF] * (m + 1)
    closed[0] = 0
    # cur[k]: {running AND of the open k-th part: min sum of the k closed parts before it}
    cur = [dict() for _ in range(m)]

    for x in nums:
        new_cur = [dict() for _ in range(m)]
        for k in range(m):
            target = andValues[k]
            d = new_cur[k]
            for a, c in cur[k].items():  # extend the open part
                na = a & x
                if na & target == target and c < d.get(na, INF):
                    d[na] = c
            if closed[k] < INF:  # start the k-th part at x
                if x & target == target and closed[k] < d.get(x, INF):
                    d[x] = closed[k]
        new_closed = [INF] * (m + 1)
        for k in range(m):
            for a, c in new_cur[k].items():
                if a == andValues[k] and c + x < new_closed[k + 1]:
                    new_closed[k + 1] = c + x  # close the k-th part at x
        cur, closed = new_cur, new_closed

    return closed[m] if closed[m] < INF else -1
